const $=id=>document.getElementById(id);
let revised=false, experiment=false, orderApplied=false, orderPreview=false;
const originalClaim='Price is causing the decline in conversion.';
const revisedClaim='Pricing may contribute to declining conversion, but we have not isolated its effect.';
function insight(title,text,actions=[]){$('insight').hidden=false;$('insight-title').textContent=title;$('insight-text').textContent=text;$('insight-actions').replaceChildren();for(const [label,fn] of actions){const b=document.createElement('button');b.className='button';b.textContent=label;b.addEventListener('click',fn);$('insight-actions').append(b)}}
function examine(){  $('claim').setAttribute('aria-expanded','true'); insight('The evidence does not establish causation.','Price objections make pricing a plausible explanation. They do not establish that it caused the conversion decline. Suggested revision: “'+revisedClaim+'”',[['Accept claim revision',revise],['Keep original claim',()=>{insight('Original claim kept.','The causal uncertainty remains. You can revisit it before sharing.');$('claim').setAttribute('aria-expanded','false');}]]); }
function revise(){revised=true;$('claim').textContent=revisedClaim;insight('One recommendation needs another look.','A broad 30% price reduction still depends on the causal claim you just weakened. More conversions may not offset lower revenue per customer or customer downgrades.',[['Preview a smaller experiment',previewExperiment],['Undo claim revision',reset]]);updateBrief();}
function previewExperiment(){insight('A reversible next step.','Proposed recommendation: run a controlled pricing experiment before committing to a broad reduction. Compare conversion, revenue per customer, and downgrades. This is a suggestion, not a validated business outcome.',[['Accept recommendation',()=>{experiment=true;$('recommendation').textContent='We recommend a controlled pricing experiment before committing to a broad reduction. Evaluate conversion, revenue per customer, and downgrades before expanding it.';insight('What would change your mind?','Reconsider the experiment if new evidence points to another cause of the decline. Reconsider a broad rollout if conversion gains fail to offset lower revenue or increased downgrades.',[['View decision brief',showBrief],['Undo recommendation',()=>{experiment=false;renderRecommendation();revise();}]]);updateBrief();}],['Back to the concern',revise]]);}
function renderRecommendation(){$('recommendation').textContent=experiment?'We recommend a controlled pricing experiment before committing to a broad reduction. Evaluate conversion, revenue per customer, and downgrades before expanding it.':'We recommend reducing the entry-level price by 30% to improve conversion.';}
function reset(){revised=false;experiment=false;$('claim').textContent=originalClaim;renderRecommendation();$('insight').hidden=true;$('claim').setAttribute('aria-expanded','false');updateBrief();}
function updateBrief(){const box=$('decision-brief');box.replaceChildren();for(const [heading,text] of [['Decision brief',experiment?'Run a controlled pricing experiment before a broad reduction.':'Proposed: reduce entry-level pricing by 30%.'],['Why',revised?'Conversion has declined. Pricing may contribute, but causation remains unestablished.':'The original memo attributes the decline to pricing; the available evidence does not establish that claim.'],['Unresolved','Pricing elasticity, changes in acquisition mix, customer downgrades, and net revenue impact.'],['Reconsider when','New causal evidence emerges, or the measured revenue effect fails to support the recommendation.']]){const h=document.createElement('h3');h.textContent=heading;const p=document.createElement('p');p.textContent=text;box.append(h,p);}const p=document.createElement('p');p.className='muted';p.textContent='Illustrative summary of this example. Review before using; no quality score or readiness guarantee.';box.append(p);}
function showBrief(){updateBrief();$('decision-brief').hidden=false;$('decision-brief').scrollIntoView({behavior:'smooth',block:'nearest'});}
function renderSpine(){const list=$('spine-list');list.replaceChildren();for(const t of (orderPreview?['Recommendation','Observed conversion decline','Possible explanation','Uncertainty and next evidence']:['Observed conversion decline','Possible explanation','Recommendation','Uncertainty and next evidence'])){const li=document.createElement('li');li.textContent=t;list.append(li);}}
$('claim').onclick=examine;$('examine').onclick=examine;$('brief').onclick=showBrief;$('shape').onclick=()=>{$('spine').hidden=!$('spine').hidden;renderSpine();};$('move-first').onclick=()=>{orderPreview=true;renderSpine();$('shape-status').textContent='Preview only: lead with the recommendation, then explain the evidence.';};$('apply-order').onclick=()=>{if(!orderPreview){$('shape-status').textContent='Choose a preview first.';return;}const article=document.querySelector('.lesson-page');article.insertBefore($('recommendation'),article.querySelector('h2').nextSibling);orderApplied=true;$('shape-status').textContent='Recommendation moved first. Wording is unchanged; check the transitions before sharing.';};$('reset-order').onclick=()=>{if(orderApplied)$('claim').after($('recommendation'));orderApplied=false;orderPreview=false;renderSpine();$('shape-status').textContent='Original order restored.';};
const modal=$('availability');document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{$('plan-name').textContent=b.dataset.plan;modal.showModal();});document.querySelector('.close').onclick=()=>modal.close();$('modal-sample').onclick=()=>{modal.close();$('practice').scrollIntoView({behavior:'smooth'});$('examine').focus({preventScroll:true});};

// Selectable, sequential method emphasis without extra explanatory copy.
const methodRows=[...document.querySelectorAll('.hero-methods li')];
let methodIndex=0;
let methodInteracting=false;
function selectMethod(index){methodIndex=index;methodRows.forEach((row,i)=>{row.classList.toggle('method-active',i===index);row.querySelector('button')?.setAttribute('aria-pressed',String(i===index));});}
methodRows.forEach((row,index)=>{
 const number=row.querySelector('.step-number');const name=row.querySelector('.method-name');
 const button=document.createElement('button');button.className='method-select';button.append(number,name);row.prepend(button);
 button.addEventListener('click',()=>selectMethod(index));
});
const methodPanel=document.querySelector('.hero-methods');
if(methodPanel){methodPanel.addEventListener('mouseenter',()=>methodInteracting=true);methodPanel.addEventListener('mouseleave',()=>methodInteracting=false);methodPanel.addEventListener('focusin',()=>methodInteracting=true);methodPanel.addEventListener('focusout',event=>{if(!methodPanel.contains(event.relatedTarget))methodInteracting=false;});}
if(methodRows.length){selectMethod(0);if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>{if(!document.hidden&&!methodInteracting)selectMethod((methodIndex+1)%methodRows.length);},2400);}
